{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "Still, criticism remains. First, some studies have raised doubts about the underlying proposed volume-­ outcome relationship. 17 18 Furthermore, uniform international guidance for minimum volume standards is seldom established, resulting, for example, in different cut-­ off thresholds and different regulatory approaches across different countries. 15 Last, different effects of minimum volume standards have been discussed in the literature, including adverse effects such as an expansion of indications as well as a threat to emergency care. 19 At the same time, there is no reported systematic review collating evidence on the effects of minimum volume standards in hospitals.",
      "reason": "The text describes existing debate/uncertainties (doubts about the volume-outcome relationship, lack of uniform guidance, possible adverse effects) and notes the evidence gap that no systematic review collates effects."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "At the same time, there is no reported systematic review collating evidence on the effects of minimum volume standards in hospitals. ... This systematic review aims to address this research gap.",
      "reason": "The introduction states the lack of a systematic review and explicitly explains that the review is conducted to address this gap."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "At the same time, there is no reported systematic review collating evidence on the effects of minimum volume standards in hospitals. In Germany, a rapid review was published in 2012 by the Institute for Quality and Efficiency in Healthcare (IQWiG).",
      "reason": "The evidence references a prior related review (the 2012 IQWiG rapid review) in the context of explaining the research gap for systematic review evidence."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PARTIAL",
      "chunk_id": "text_0",
      "quote": "relationship according to which higher case volumes are associated with improved outcomes. 2 3 In fact, evidence for a volume-­ outcome relationship has been accumulated for various medical interventions including surgeries, dialysis, perinatal as well as intensive care. 4-14 Based on these findings, minimum volume standards have been introduced in numerous countries, particularly for highly specialised surgical procedures. 15 16",
      "reason": "A proposed rationale/mechanistic premise (higher volumes -> improved outcomes; basis for introducing minimum volume standards) is described, but the evidence does not clearly spell out a brief mechanism of action of the specific intervention in terms of how minimum volume standards are expected to affect outcomes."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No logic model or hypothesised relationships between intervention components and outcomes are described in the retrieved evidence."
    }
  ],
  "confidence": 74
}

