{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "We included the following study designs: (Cluster) randomised controlled trials ((C)RCTs) Non-­ randomised controlled trials (nRCTs) Controlled before-­ after (CBA) studies. Interrupted time series (ITS) with a clearly defined time point of intervention introduction and at least three data points both before and after the intervention. Health Care . (C)RCTs are often not available to address questions about health system interventions. Therefore, we included other study designs based on the recommendations by the Cochrane Effective Practice and Organisation of Care (EPOC) group. The study design was determined using the Cochrane EPOC group algorithm. 25 No restrictions were placed on language, publication date or publication status of the studies.",
      "reason": "The review specifies eligible study designs and an ITS follow-up/data-point requirement, but it does not clearly specify all other study-characteristic components relevant to eligibility (e.g., settings and follow-up requirements beyond the ITS criterion)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "No restrictions were placed on language, publication date or publication status of the studies.",
      "reason": "Language, publication date, and publication status are addressed (i.e., no restrictions), but there is no explicit specification of eligibility criteria for report characteristics beyond that (e.g., the exact dissemination year criteria)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no statement distinguishing exclusions because outcomes were not measured versus exclusions because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The evidence does not report how groups used in each synthesis were specified or linked to the review’s objective-defined comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_27",
      "quote": "This is mostly due to our restriction to only include studies with a robust study design (eg, CBA or ITS studies).",
      "reason": "A rationale is provided for a notable eligibility restriction (only include robust study designs), but the evidence does not comprehensively document rationales for other notable restrictions."
    }
  ],
  "confidence": 66
}

